export const meta = {
  name: 'singleton-pr-sweep',
  description: 'Review 14 singleton-author PRs on gastownhall/beads (sonnet reviewers; codex verifies later)',
  phases: [{ title: 'Review', detail: 'one sonnet reviewer per PR' }],
}

const PRS = [
  { n: 4984, author: 'davevan2', hint: 'create: reject caller input that would be discarded. CHANGES_REQUESTED 07-23; check if author pushed since.' },
  { n: 4985, author: 'davevan2', hint: 'keep preview commands from migrating stores. CHANGES_REQUESTED 07-23; check if author pushed since. Same author as 4984 — check for overlap between the two.' },
  { n: 4897, author: 'jacobhausler', hint: 'ready pagination metadata under BD_JSON_ENVELOPE=1 when truncated. SUPERSESSION SUSPECT: BEADS_MAX_ROWS behavioral work merged via #4160 (07-24) and the bd ready --json MaxRows cap follow-up landed recently — compare what main does now on truncation before any verdict.' },
  { n: 4918, author: 'jacobhausler', hint: 'create: reject --waits-for-gate when --waits-for absent + regression tests. Small validation fix.' },
  { n: 4858, author: 'vishnujayvel', hint: 'doctor: detect orphaned child_counters rows (gh#4539).' },
  { n: 4913, author: 'vishnujayvel', hint: 'docs(async-gates): fix nonexistent gate subcommands in skill resource. Docs-only; verify the corrected commands actually exist in current bd.' },
  { n: 4896, author: 'anisoptera', hint: 'query: slash and mixed-case metadata keys queryable. Author is active (their #4877 merged 07-24 including metadata-related --graph work) — check overlap with #4877 and whether CHANGES_REQUESTED items were addressed.' },
  { n: 4930, author: 'idirectships', hint: 'readonly: prevent validation side effects.' },
  { n: 4940, author: 'imkp1', hint: 'test(backup): platform-native absolute path in TestResolveDoltBackupURL (gh#4923). Tiny test fix, no review decision yet — likely easy-win.' },
  { n: 4862, author: 'itsandyking', hint: 'claim: serialize concurrent claims with per-database advisory lock. STRONG SUPERSESSION SUSPECT: --claim is already a hard CAS for distinct actors (conditional UPDATE + RowsAffected + row_lock commit-conflict, since GH-3570/#4537), and #5006 (verify-by-re-read) + #5008 (--if-assignee/--if-status) merged 07-24. Determine what residual problem, if any, an advisory lock solves (e.g. embedded-mode lock contention) before any verdict.' },
  { n: 4939, author: 'joshuaguyervs', hint: 'reject substring matches in ID resolution, require exact hash match only. Cross-check against the partial-ID resolution work just fix-merged on #4910 (utils.ResolvePartialID, ErrAmbiguousID) — are these complementary or conflicting semantics?' },
  { n: 4866, author: 'RaviTharuma', hint: 'routing: warn when contributor auto-routing swaps bd list/ready to the planning store.' },
  { n: 4959, author: 'srobroek', hint: 'gate: honor repository metadata for GitHub checks.' },
  { n: 4933, author: 'swedeinasia-flow', hint: 'doctor: bound dependency-cycle check queries, match bd dep cycles semantics.' },
]

const TARGET = budget.total ?? 200_000
const START = budget.spent()

const REVIEW_SCHEMA = {
  type: 'object',
  properties: {
    pr: { type: 'integer' },
    classification: { type: 'string', enum: ['merge', 'merge-fix', 'fix-merge', 'easy-win', 'retire', 'reject', 'needs-author', 'needs-deeper-review'] },
    maintainer_can_edit: { type: 'boolean' },
    behind_main: { type: 'string' },
    changes_requested_state: { type: 'string', description: 'what any CHANGES_REQUESTED review asked and whether addressed at current head; "none" if no review' },
    supersession: { type: 'string', description: 'merged main work covering this PR (commits/PRs), or "none"' },
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          file: { type: 'string' },
          issue: { type: 'string' },
          fix: { type: 'string' },
          blocking: { type: 'boolean' },
        },
        required: ['file', 'issue', 'fix', 'blocking'],
      },
    },
    action_plan: { type: 'string' },
    risk: { type: 'string', enum: ['low', 'medium', 'high'] },
  },
  required: ['pr', 'classification', 'maintainer_can_edit', 'behind_main', 'changes_requested_state', 'supersession', 'findings', 'action_plan', 'risk'],
}

const RULES = `Ground rules:
- Read-only. Do NOT run any bd or dolt command. Do NOT edit/write files. Do NOT post anything to GitHub.
- Work from /var/home/matt/dev/mybd. Upstream repo: gastownhall/beads — always pass --repo gastownhall/beads to gh. Beads source clone: bd-main/ (git -C bd-main; upstream remote = gastownhall/beads). Do not create refs; use gh pr diff, or fetch to FETCH_HEAD only.
- Maintainer philosophy (PR_MAINTAINER_GUIDELINES.md): maximize contributor value; prefer fix-merge over request-changes; retire only when genuinely superseded, with credit and a precise account of what landed where.
- Cite findings as file:line, concrete enough for a builder to apply without rediscovery.`

phase('Review')
const reviews = await pipeline(
  PRS,
  (p) => {
    if (budget.spent() - START > TARGET * 0.9) {
      log(`budget guard: skipping review for PR ${p.n}`)
      return null
    }
    return agent(
      `Maintainer review of gastownhall/beads PR #${p.n} by ${p.author} (singleton-author sweep).

Hint: ${p.hint}

Gather: gh pr view ${p.n} --repo gastownhall/beads --json title,body,state,mergeable,maintainerCanModify,headRefName,headRepositoryOwner,statusCheckRollup,createdAt ; full review history (--json reviews,comments + gh api repos/gastownhall/beads/pulls/${p.n}/comments) — determine exactly what any CHANGES_REQUESTED review demanded and whether the CURRENT head addresses it; the diff (gh pr diff ${p.n}); supersession/drift vs upstream/main (git -C bd-main log upstream/main --oneline -- <paths>, read merged diffs where the hint names suspects); correctness of the change itself.

Classify per maintainer triage groups; action_plan must be concrete (exact fixes for fix-merge, credit text for retire).

${RULES}`,
      { label: `review:${p.author.slice(0, 7)}:${p.n}`, phase: 'Review', model: 'sonnet', schema: REVIEW_SCHEMA }
    )
  }
)

log(`spent ~${Math.round((budget.spent() - START) / 1000)}k of ${Math.round(TARGET / 1000)}k target (this workflow)`)
return { reviews: reviews.filter(Boolean) }

